{"command":"python3 - <<'PY'
import pty, os, subprocess, select, time

def run(args, stdout_tty=False, stderr_tty=False, env_extra=None):
    # create ptys as needed
    masters=[]
    slaves_stdout=None; slaves_stderr=None
    m_out=s_out=None; m_err=s_err=None
    if stdout_tty:
        m_out,s_out=pty.openpty()
    if stderr_tty:
        if stdout_tty:
            # use same? use separate
            m_err,s_err=pty.openpty()
        else:
            m_err,s_err=pty.openpty()
    env=dict(os.environ)
    if env_extra: env.update(env_extra)
    # if not tty use PIPE
    p=subprocess.Popen(["./executable"]+args,
        stdout=s_out if stdout_tty else subprocess.PIPE,
        stderr=s_err if stderr_tty else subprocess.PIPE,
        stdin=subprocess.DEVNULL, env=env)
    if s_out: os.close(s_out)
    if s_err: os.close(s_err)
    out_pipe=b""; err_pipe=b""
    if not stdout_tty or not stderr_tty:
        # communicate will read pipes but tty data need manual; simplify: if one tty and other pipe, use communicate trick? Popen communicate reads pipes ignoring tty fd
        pass
    # Read tty masters with timeout while process runs
    out_tty=b""; err_tty=b""
    # set nonblocking?
    import fcntl
    for m in [m_out,m_err]:
        if m is not None:
            fcntl.fcntl(m, fcntl.F_SETFL, os.O_NONBLOCK)
    start=time.time()
    while time.time()-start<8:
        if p.poll() is not None:
            # drain a bit
            time.sleep(0.2)
            for m, name in [(m_out,'out'),(m_err,'err')]:
                if m is not None:
                    try:
                        while True:
                            d=os.read(m,8192)
                            if not d: break
                            if name=='out': out_tty+=d
                            else: err_tty+=d
                    except OSError: pass
            break
        r,_,_=select.select([m for m in [m_out,m_err] if m is not None],[],[],0.2) if (m_out or m_err) else ([],[],[])
        for m in r:
            try: d=os.read(m,8192)
            except OSError: d=b''
            if m==m_out: out_tty+=d
            else: err_tty+=d
        # if no tty, just wait
        if not (m_out or m_err):
            break
    if not stdout_tty and not stderr_tty:
        out_pipe,err_pipe=p.communicate(timeout=5)
        print(f"args={args} tty_out={stdout_tty} tty_err={stderr_tty} env={env_extra} rc={p.returncode} stdout={out_pipe!r} stderr={err_pipe!r}")
        return
    # for mixed, pipes need reading after process? Communicate would conflict? We can try read from p.stdout
    if p.poll() is None:
        try: p.wait(timeout=3)
        except: p.kill()
    pipe_out=b""; pipe_err=b""
    if not stdout_tty and p.stdout:
        pipe_out=p.stdout.read() or b''
    if not stderr_tty and p.stderr:
        pipe_err=p.stderr.read() or b''
    print(f"args={args} tty_out={stdout_tty} tty_err={stderr_tty} env={env_extra} rc={p.returncode} tty_stdout={out_tty!r} tty_stderr={err_tty!r} pipe_stdout={pipe_out!r} pipe_stderr={pipe_err!r}")
    for m in [m_out,m_err]:
        if m:
            try: os.close(m)
            except: pass

# error case
run([], stdout_tty=False, stderr_tty=False)
run([], stdout_tty=True, stderr_tty=False)
run([], stdout_tty=False, stderr_tty=True)
run([], stdout_tty=True, stderr_tty=True)
print("--- ping success combos")
run(["-c","1","127.0.0.1"], stdout_tty=True, stderr_tty=False)
run(["-c","1","127.0.0.1"], stdout_tty=False, stderr_tty=True)
PY"}

