{"command":"python3 - <<'PY'
import pty, os, subprocess, select, time, fcntl
def run_pty(args, env_extra=None):
    master, slave = pty.openpty()
    env=dict(os.environ); 
    if env_extra:
        for k,v in env_extra.items():
            if v is None: env.pop(k,None)
            else: env[k]=v
    p=subprocess.Popen(["./executable"]+args, stdout=slave, stderr=slave, stdin=subprocess.DEVNULL, env=env)
    os.close(slave)
    fcntl.fcntl(master, fcntl.F_SETFL, os.O_NONBLOCK)
    out=b""; start=time.time()
    while time.time()-start<8:
        if p.poll() is not None:
            time.sleep(0.2)
            try:
                while True:
                    d=os.read(master,8192)
                    if not d: break
                    out+=d
            except OSError: pass
            break
        r,_,_=select.select([master],[],[],0.2)
        if r:
            try: out+=os.read(master,8192)
            except: pass
    print(f"env={env_extra} rc={p.returncode} out={out!r}")
    os.close(master)

for env in [{"TERM":"dumb"},{"TERM":""},{"NO_COLOR":"1"},{"NO_COLOR":""},{"FORCE_COLOR":"1"},{"CLICOLOR":"0"},{"CLICOLOR_FORCE":"1"},{"TERM":"xterm"}, {"TERM":None}]:
    run_pty([], env_extra=env)
for env in [{"TERM":"dumb"},{"NO_COLOR":"1"},{"FORCE_COLOR":"1"}]:
