import pty, os, subprocess, select, time, fcntl
def run_pty(args, env_extra=None):
    master, slave = pty.openpty()
    env=dict(os.environ)
    if env_extra:
        for k,v in env_extra.items():
            if v is None: env.pop(k,None)
            else: env[k]=v
    p=subprocess.Popen(["./executable"]+args, stdout=slave, stderr=slave, stdin=subprocess.DEVNULL, env=env)
    os.close(slave)
    fcntl.fcntl(master, fcntl.F_SETFL, os.O_NONBLOCK)
    out=b""; start=time.time()
    while time.time()-start<5:
        if p.poll() is not None:
            time.sleep(0.15)
            try:
                while True:
                    d=os.read(master,8192)
                    if not d: break
                    out+=d
            except: pass
            break
        r,_,_=select.select([master],[],[],0.2)
        if r:
            try: out+=os.read(master,8192)
            except: pass
    os.close(master)
    print(env_extra, p.returncode, repr(out))
for env in [{"NO_COLOR":"0"},{"NO_COLOR":"false"},{"TERM":"DUMB"},{"TERM":"dumb "},{"TERM":" dumb"},{"CLICOLOR":"0"}]:
    run_pty([], env)
