{"command":"mkdir -p /tmp/proto && cat > /tmp/proto/main.go <<'GO'
package main

import (
 "fmt"
 "os"
 "syscall"
 "time"
)

func cksum(b []byte) uint16 {
 var sum uint32
 for i:=0;i+1<len(b);i+=2 { sum+=uint32(b[i])<<8|uint32(b[i+1]) }
 if len(b)%2==1 { sum+=uint32(b[len(b)-1])<<8 }
 for sum>>16!=0 { sum=(sum&0xffff)+(sum>>16) }
 return ^uint16(sum)
}
func main(){
 ipv6 := len(os.Args)>1 && os.Args[1]=="6"
 var fd int
 var err error
 var dest syscall.Sockaddr
 if ipv6 {
   fd, err = syscall.Socket(syscall.AF_INET6, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMPV6)
   if err!=nil{panic(err)}
   syscall.SetsockoptInt(fd, syscall.IPPROTO_IPV6, 51, 1) // recvhoplimit?
   // try constants print
   err=syscall.Bind(fd, &syscall.SockaddrInet6{Port:0})
   dest=&syscall.SockaddrInet6{Port:0, Addr:[16]byte{15:1}}
 } else {
   fd, err = syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
   if err!=nil{panic(err)}
   fmt.Println("setsockopt ttl recv", syscall.SetsockoptInt(fd, syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1))
   err=syscall.Bind(fd, &syscall.SockaddrInet4{Port:0})
   dest=&syscall.SockaddrInet4{Port:0, Addr:[4]byte{127,0,0,1}}
 }
 if err!=nil{panic(err)}
 sa, _ := syscall.Getsockname(fd)
 fmt.Printf("local %#v\n", sa)
 data:=make([]byte,24)
 for i:=range data{data[i]=byte(i)}
 typ:=byte(8); if ipv6{typ=128}
 msg:=make([]byte,8+len(data))
 msg[0]=typ
 msg[6]=0; msg[7]=0 // seq 0
 copy(msg[8:],data)
 if !ipv6 {
   cs:=cksum(msg); msg[2]=byte(cs>>8); msg[3]=byte(cs)
 }
 start:=time.Now()
 err=syscall.Sendto(fd, msg, 0, dest)
 fmt.Println("send err",err, time.Since(start))
 buf:=make([]byte,2048); oob:=make([]byte,1024)
 n,oobn,_,addr,err:=syscall.Recvmsg(fd,buf,oob,0)
 fmt.Println("recv",n,oobn,addr,err,time.Since(start))
 fmt.Printf("data % x\n",buf[:n])
 if oobn>0 {
   cms,_:=syscall.ParseSocketControlMessage(oob[:oobn])
   for _,c:=range cms{ fmt.Printf("cmsg level=%d type=%d data=%v\n",c.Header.Level,c.Header.Type,c.Data)}
 }
 // second packet seq1
 msg[7]=1
 if !ipv6 { msg[2]=0;msg[3]=0; cs:=cksum(msg); msg[2]=byte(cs>>8); msg[3]=byte(cs)}
 syscall.Sendto(fd,msg,0,dest)
 n,oobn,_,addr,err=syscall.Recvmsg(fd,buf,oob,0)
 fmt.Println("recv2",n,oobn,addr,err)
 fmt.Printf("data % x\n",buf[:n])
 if oobn>0 { cms,_:=syscall.ParseSocketControlMessage(oob[:oobn]); for _,c:=range cms{ fmt.Printf("cmsg level=%d type=%d data=%v\n",c.Header.Level,c.Header.Type,c.Data)} }
}
GO
cd /tmp/proto && go mod init proto >/dev/null 2>&1; go run . ; echo ---v6; go run . 6"}

