// ---------------------------------------------------------------------------
// Colour output
//
// The tool prints plain text when stdout is not a terminal. When it is a
// terminal, selected words are highlighted. Colours are disabled when
// TERM=dumb or when NO_COLOR is set to a non-empty value.
// ---------------------------------------------------------------------------

var colourEnabled = detectColour()

func detectColour() bool {
	if os.Getenv("TERM") == "dumb" {
		return false
	}
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	var termios syscall.Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(),
		uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)))
	return errno == 0
}

// inline returns text wrapped in a bold colour when colour is enabled.
// The terminating sequence clears attributes (0) and bold (22).
func inline(code, text string) string {
	if !colourEnabled {
		return text
	}
	return "\x1b[" + code + "m" + text + "\x1b[0;22m"
}

// printColouredLine prints a whole line (including its newline) in a bold
// colour, terminated by a plain reset.
func printColouredLine(code, text string) {
	if colourEnabled {
		fmt.Fprintf(os.Stdout, "\x1b[%sm%s\x1b[0m", code, text)
		return
	}
	fmt.Fprint(os.Stdout, text)
}

func printErrorLine(message string) {
	fmt.Fprintf(os.Stderr, "[ %s ] %s\n", inline("31;1", "ERROR"), message)
}

