// ---------------------------------------------------------------------------

const helpText = "Usage:\n" +
	"  pingu [OPTIONS] HOST\n" +
	"\n" +
	"`ping` command but with pingu\n" +
	"\n" +
	"Application Options:\n" +
	"  -c, --count=     Stop after <count> replies (default: 20)\n" +
	"  -P, --privilege  Enable privileged mode\n" +
	"  -V, --version    Show version\n" +
	"\n" +
	"Help Options:\n" +
	"  -h, --help       Show this help message\n" +
	"\n"

const versionText = "pingu: v-rev8ff82f4"

var errHelpRequested = errors.New("help requested")

type flagDef struct {
	short   rune
	long    string
	display string // e.g. "-c, --count"
	hasArg  bool
}

var (
	countFlag     = flagDef{short: 'c', long: "count", display: "-c, --count", hasArg: true}
	privilegeFlag = flagDef{short: 'P', long: "privilege", display: "-P, --privilege"}
	versionFlag   = flagDef{short: 'V', long: "version", display: "-V, --version"}
	helpFlag      = flagDef{short: 'h', long: "help", display: "-h, --help"}
)

func shortFlag(r rune) (flagDef, bool) {
	switch r {
	case 'c':
		return countFlag, true
	case 'P':
		return privilegeFlag, true
	case 'V':
		return versionFlag, true
	case 'h':
		return helpFlag, true
	}
	return flagDef{}, false
}

func longFlag(name string) (flagDef, bool) {
	switch name {
	case "count":
		return countFlag, true
	case "privilege":
		return privilegeFlag, true
	case "version":
		return versionFlag, true
	case "help":
		return helpFlag, true
	}
	return flagDef{}, false
}

type options struct {
	count      int
	privilege  bool
	version    bool
	positional []string
}

func isOptionToken(arg string) bool {
	if len(arg) >= 2 && arg[0] == '-' && arg[1] == '-' {
		return len(arg) > 2 && arg[2] != '-'
	}
	return len(arg) >= 2 && arg[0] == '-' && arg[1] != '-'
}

// isOptionNext reports whether a token following a flag that needs a value
// should be rejected as another option. Tokens such as "-1" are treated as
// values (negative numbers), as are non-option tokens such as "-" and
// "---x".
func isOptionNext(arg string) bool {
	if !isOptionToken(arg) {
		return false
	}
	if arg[1] != '-' && len(arg) >= 2 && arg[1] >= '0' && arg[1] <= '9' {
		return false
	}
	return true
