		p.opts.positional = append(p.opts.positional, arg)
		return nil
	}
	first := chars[0]
	def, ok := shortFlag(first)
	if !ok {
		return fmt.Errorf("unknown flag `%c'", first)
	}
	// A flag that takes a value consumes the rest of the token.
	if def.hasArg {
		if len(chars) == 1 {
			v, err := p.nextValue()
			if err != nil {
				return err
			}
			return p.setCount(v)
		}
		rest := arg[1+len(string(first)):]
		if strings.HasPrefix(rest, "=") {
			rest = rest[1:]
		}
		return p.setCount(rest)
	}
	// Single bool flag, possibly written as -P=value.
	if len(chars) > 1 && chars[1] == '=' {
		return fmt.Errorf("bool flag `%s' cannot have an argument", def.display)
	}
	if len(chars) == 1 {
		if def.short == 'h' {
			return errHelpRequested
		}
		if def.short == 'P' {
			p.opts.privilege = true
		} else if def.short == 'V' {
			p.opts.version = true
		}
		return nil
	}
	// A group of short flags, e.g. -PV. A value-taking flag in a group must
	// be the last character and takes its value from the next argument.
	for idx, ch := range chars {
		d, ok := shortFlag(ch)
		if !ok {
			return fmt.Errorf("unknown flag `%c'", ch)
		}
		if d.short == 'h' {
			return errHelpRequested
		}
		if !d.hasArg {
			if d.short == 'P' {
				p.opts.privilege = true
			} else if d.short == 'V' {
				p.opts.version = true
			}
			continue
		}
		// count inside a group
		if idx != len(chars)-1 {
			return fmt.Errorf("expected argument for flag `%s'", countFlag.display)
		}
		v, err := p.nextValue()
		if err != nil {
			return err
		}
		if err := p.setCount(v); err != nil {
			return err
		}
	}
	return nil
}

func parseArgs(args []string) (*options, error) {
	opts := &options{count: 20}
	p := &parser{args: args, opts: opts}
	afterDashDash := false
	for p.pos < len(args) {
		arg := args[p.pos]
		p.pos++
		if afterDashDash {
			opts.positional = append(opts.positional, arg)
			continue
		}
		if arg == "--" {
			afterDashDash = true
			continue
		}
		if !isOptionToken(arg) {
			opts.positional = append(opts.positional, arg)
			continue
		}
		var err error
		if len(arg) >= 2 && arg[1] == '-' {
			err = p.parseLong(arg)
		} else {
			err = p.parseShort(arg)
		}
		if err != nil {
			return nil, err
		}
	}
	return opts, nil
}

// ---------------------------------------------------------------------------
// Ping engine (ICMP echo over a datagram "ping" socket, or a raw socket in
// privileged mode)
// ---------------------------------------------------------------------------

const (
	icmpEchoRequestV4 = 8
	icmpEchoReplyV4   = 0
	icmpEchoRequestV6 = 128
	icmpEchoReplyV6   = 129

	ipv6RecvHopLimit = 51 // IPV6_RECVHOPLIMIT
	ipv6HopLimit     = 52 // IPV6_HOPLIMIT control message type
)

type receivedPacket struct {
	seq  int
	size int
	ttl  int
	when time.Time
}

type pingEngine struct {
	host       string
	ipAddr     *net.IPAddr
	ipv4       bool
	privileged bool
	count      int

	fd        int
	localPort int
	id        int

	sent      int
	received  int
	sentTimes map[int]time.Time // wire sequence -> send time
	delivered map[int]bool
	rtts      []time.Duration

	statsShown bool
}

func checksum(data []byte) uint16 {
	var sum uint32
	for i := 0; i+1 < len(data); i += 2 {
		sum += uint32(data[i])<<8 | uint32(data[i+1])
	}
	if len(data)%2 == 1 {
		sum += uint32(data[len(data)-1]) << 8
	}
	for sum>>16 != 0 {
		sum = (sum & 0xffff) + (sum >> 16)
	}
	return ^uint16(sum)
}

func (e *pingEngine) destination() syscall.Sockaddr {
	if e.ipv4 {
		var a [4]byte
		copy(a[:], e.ipAddr.IP.To4())
		return &syscall.SockaddrInet4{Addr: a}
	}
	var a [16]byte
	copy(a[:], e.ipAddr.IP.To16())
	sa := &syscall.SockaddrInet6{Addr: a}
	sa.ZoneId = uint32(zoneScopeID(e.ipAddr.Zone))
	return sa
}

func zoneScopeID(zone string) int {
	if zone == "" {
		return 0
	}
	if iface, err := net.InterfaceByName(zone); err == nil {
		return iface.Index
	}
	if n, err := strconv.Atoi(zone); err == nil {
		return n
	}
	return 0
}

func (e *pingEngine) destDisplay() string {
	return e.ipAddr.String()
}

func (e *pingEngine) localDisplay() string {
	if e.ipv4 {
		return fmt.Sprintf("0.0.0.0:%d", e.localPort)
	}
	return fmt.Sprintf("[::]:%d", e.localPort)
}

func (e *pingEngine) remoteDisplay() string {
	if e.ipv4 {
		return e.destDisplay() + ":0"
	}
	return "[" + e.destDisplay() + "]:0"
}

func errnoText(err error) string {
	if err == nil {
		return ""
	}
	var errno syscall.Errno
	if errors.As(err, &errno) {
		return errno.Error()
	}
	return err.Error()
}

// openSocket creates and (for the datagram case) binds the socket. An error
// returned here is reported without statistics.
func (e *pingEngine) openSocket() error {
	if e.privileged {
		var domain, proto int
		var network string
		if e.ipv4 {
			domain, proto, network = syscall.AF_INET, syscall.IPPROTO_ICMP, "ip4:icmp"
		} else {
			domain, proto, network = syscall.AF_INET6, syscall.IPPROTO_ICMPV6, "ip6:ipv6-icmp"
		}
		fd, err := syscall.Socket(domain, syscall.SOCK_RAW, proto)
		if err != nil {
			return fmt.Errorf("listen %s : socket: %s", network, errnoText(err))
		}
		e.fd = fd
		e.id = os.Getpid() & 0xffff
		e.setTTLReceiveOption()
		return nil
	}

	var domain, proto int
	if e.ipv4 {
		domain, proto = syscall.AF_INET, syscall.IPPROTO_ICMP
	} else {
		domain, proto = syscall.AF_INET6, syscall.IPPROTO_ICMPV6
	}
	fd, err := syscall.Socket(domain, syscall.SOCK_DGRAM, proto)
	if err != nil {
		return fmt.Errorf("listen udp %s: socket: %s", e.openLocalDisplay(), errnoText(err))
	}
	var bindAddr syscall.Sockaddr
	if e.ipv4 {
		bindAddr = &syscall.SockaddrInet4{}
	} else {
		bindAddr = &syscall.SockaddrInet6{}
	}
	if err := syscall.Bind(fd, bindAddr); err != nil {
		syscall.Close(fd)
		return fmt.Errorf("listen udp %s: bind: %s", e.openLocalDisplay(), errnoText(err))
	}
	e.fd = fd
	if sa, err := syscall.Getsockname(fd); err == nil {
		switch s := sa.(type) {
		case *syscall.SockaddrInet4:
			e.localPort = s.Port
		case *syscall.SockaddrInet6:
			e.localPort = s.Port
		}
	}
	e.id = e.localPort
	e.setTTLReceiveOption()
	return nil
}

func (e *pingEngine) openLocalDisplay() string {
	if e.ipv4 {
		return "0.0.0.0:0"
	}
	return "[::]:0"
}

func (e *pingEngine) setTTLReceiveOption() {
	if e.ipv4 {
		syscall.SetsockoptInt(e.fd, syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1)
	} else {
		syscall.SetsockoptInt(e.fd, syscall.IPPROTO_IPV6, ipv6RecvHopLimit, 1)
	}
}

func (e *pingEngine) writeError(err error) error {
	if e.privileged {
		network := "ip4:icmp"
		if !e.ipv4 {
			network = "ip6:ipv6-icmp"
		}
		return fmt.Errorf("write %s %s: sendto: %s", network, e.destDisplay(), errnoText(err))
	}
	return fmt.Errorf("write udp %s->%s: sendto: %s", e.localDisplay(), e.remoteDisplay(), errnoText(err))
}

func (e *pingEngine) readError(err error) error {
	if e.privileged {
		network := "ip4:icmp"
		if !e.ipv4 {
			network = "ip6:ipv6-icmp"
		}
		return fmt.Errorf("read %s %s: recvfrom: %s", network, e.destDisplay(), errnoText(err))
	}
	return fmt.Errorf("read udp %s: recvfrom: %s", e.localDisplay(), errnoText(err))
}

func (e *pingEngine) send(seq int) error {
	payload := make([]byte, 24)
	now := time.Now()
	binary.LittleEndian.PutUint64(payload, uint64(now.UnixNano()))
	for i := 8; i < len(payload); i++ {
		payload[i] = byte(i)
	}
	msg := make([]byte, 8+len(payload))
	if e.ipv4 {
		msg[0] = icmpEchoRequestV4
	} else {
		msg[0] = icmpEchoRequestV6
	}
	binary.BigEndian.PutUint16(msg[4:6], uint16(e.id))
	binary.BigEndian.PutUint16(msg[6:8], uint16(seq))
	copy(msg[8:], payload)
	if e.ipv4 {
		binary.BigEndian.PutUint16(msg[2:4], checksum(msg))
	}
	e.sentTimes[seq&0xffff] = now
	if err := syscall.Sendto(e.fd, msg, 0, e.destination()); err != nil {
		delete(e.sentTimes, seq&0xffff)
		return e.writeError(err)
	}
	e.sent++
	return nil
}

func (e *pingEngine) receiveLoop(packets chan<- receivedPacket, failures chan<- error) {
	buf := make([]byte, 4096)
	oob := make([]byte, 1024)
	for {
		n, oobn, _, _, err := syscall.Recvmsg(e.fd, buf, oob, 0)
		if err != nil {
			failures <- e.readError(err)
			return
		}
		when := time.Now()
		data := buf[:n]
		ttl := 0
		// Parse control messages for TTL / hop limit.
		if oobn > 0 {
			if cms, err := syscall.ParseSocketControlMessage(oob[:oobn]); err == nil {
				for _, cm := range cms {
					if e.ipv4 && cm.Header.Level == syscall.IPPROTO_IP && cm.Header.Type == syscall.IP_TTL && len(cm.Data) >= 4 {
						ttl = int(binary.LittleEndian.Uint32(cm.Data[:4]))
					}
					if !e.ipv4 && cm.Header.Level == syscall.IPPROTO_IPV6 && cm.Header.Type == ipv6HopLimit && len(cm.Data) >= 4 {
						ttl = int(binary.LittleEndian.Uint32(cm.Data[:4]))
					}
				}
			}
		}
		payload := data
		if e.privileged && e.ipv4 {
			if len(data) < 20 {
				continue
			}
			ihl := int(data[0]&0x0f) * 4
			if ihl < 20 || ihl > len(data) {
				continue
			}
			ttl = int(data[8])
			payload = data[ihl:]
		}
		if len(payload) < 8 {
			continue
		}
		replyType := byte(icmpEchoReplyV4)
		if !e.ipv4 {
			replyType = icmpEchoReplyV6
		}
		if payload[0] != replyType {
			continue
		}
		pktID := int(binary.BigEndian.Uint16(payload[4:6]))
		if e.privileged && pktID != e.id {
			continue
		}
		seq := int(binary.BigEndian.Uint16(payload[6:8]))
		packets <- receivedPacket{seq: seq, size: len(payload), ttl: ttl, when: when}
	}
}

func (e *pingEngine) showStats() {
	if e.statsShown {
		return
	}
	e.statsShown = true
	printColouredLine("37;1", fmt.Sprintf("\n───────── %s ping statistics ─────────\n", e.host))

	var packetLoss float64
	if e.sent == 0 {
		packetLoss = math.NaN()
	} else {
		packetLoss = float64(e.sent-e.received) / float64(e.sent) * 100
	}

	var minRtt, avgRtt, maxRtt, stdDevRtt time.Duration
	if len(e.rtts) > 0 {
		minRtt = e.rtts[0]
		maxRtt = e.rtts[0]
		var total time.Duration
		for _, rtt := range e.rtts {
			if rtt < minRtt {
				minRtt = rtt
			}
			if rtt > maxRtt {
				maxRtt = rtt
			}
			total += rtt
		}
		avgRtt = total / time.Duration(len(e.rtts))
		var squaredDiffs float64
		for _, rtt := range e.rtts {
			diff := float64(rtt - avgRtt)
			squaredDiffs += diff * diff
		}
		stdDevRtt = time.Duration(math.Sqrt(squaredDiffs / float64(len(e.rtts))))
	}

	fmt.Fprintf(os.Stdout, "%s: %s transmitted => %s received (%s loss)\n",
		inline("97;1", "PACKET STATISTICS"),
		inline("94;1", strconv.Itoa(e.sent)),
		inline("92;1", strconv.Itoa(e.received)),
		inline("91;1", fmt.Sprintf("%v%%", packetLoss)))
	fmt.Fprintf(os.Stdout, "%s: min=%s avg=%s max=%s stddev=%s\n",
		inline("97;1", "ROUND TRIP"),
		inline("94;1", minRtt.String()),
		inline("96;1", avgRtt.String()),
		inline("92;1", maxRtt.String()),
		inline("35;1", stdDevRtt.String()))
}

func (e *pingEngine) run() error {
	if err := e.openSocket(); err != nil {
		return err
	}
	defer syscall.Close(e.fd)

	packets := make(chan receivedPacket, 32)
	failures := make(chan error, 1)
	go e.receiveLoop(packets, failures)

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, os.Interrupt)
	defer signal.Stop(sigCh)

	seq := 0
	if err := e.send(seq); err != nil {
		e.showStats()
		return err
	}
	seq++

	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()

	for {
		select {
		case pkt := <-packets:
			if e.delivered[pkt.seq] {
				continue
			}
			sentAt, ok := e.sentTimes[pkt.seq]
			if !ok {
				continue
			}
			e.delivered[pkt.seq] = true
			rtt := pkt.when.Sub(sentAt)
			e.received++
			e.rtts = append(e.rtts, rtt)
			frame := artRows[pkt.seq%len(artRows)]
			fmt.Fprintf(os.Stdout, "%s seq=%s %sbytes from %s: ttl=%s time=%s\n",
				frame,
				inline("93;1", strconv.Itoa(pkt.seq)),
				inline("94;1", strconv.Itoa(pkt.size)),
				inline("37;1", e.destDisplay()),
				inline("96;1", strconv.Itoa(pkt.ttl)),
				inline("95;1", rtt.String()))
			if e.count > 0 && e.received >= e.count {
				e.showStats()
				return nil
			}
		case err := <-failures:
			e.showStats()
			return err
		case <-ticker.C:
			if err := e.send(seq); err != nil {
				e.showStats()
				return err
			}
			seq++
		case <-sigCh:
			e.showStats()
			return nil
		}
	}
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

func run(args []string) int {
	opts, err := parseArgs(args)
	if err != nil {
		if errors.Is(err, errHelpRequested) {
			fmt.Fprint(os.Stdout, helpText)
			return 0
		}
		fmt.Fprintln(os.Stderr, err.Error())
		printErrorLine(fmt.Sprintf("parse error: %s", err.Error()))
		return 1
	}

	if opts.version {
		fmt.Fprintln(os.Stdout, versionText)
		return 0
	}
	if len(opts.positional) == 0 {
		printErrorLine("must requires an argument")
		return 1
	}
	if len(opts.positional) > 1 {
		printErrorLine("too many arguments")
		return 1
	}
	host := opts.positional[0]

	if host == "" {
		printErrorLine("an error occurred while initializing pinger: failed to init pinger addr cannot be empty")
		return 0
	}
	ipAddr, err := net.ResolveIPAddr("ip", host)
	if err != nil {
		printErrorLine(fmt.Sprintf("an error occurred while initializing pinger: failed to init pinger %s", err.Error()))
		return 0
	}

	printColouredLine("97;1", fmt.Sprintf("PING %s (%s) type `Ctrl-C` to abort\n", host, ipAddr.String()))

	engine := &pingEngine{
		host:       host,
		ipAddr:     ipAddr,
		ipv4:       ipAddr.IP.To4() != nil,
		privileged: opts.privilege,
		count:      opts.count,
		sentTimes:  make(map[int]time.Time),
		delivered:  make(map[int]bool),
	}
	if err := engine.run(); err != nil {
		printErrorLine(fmt.Sprintf("an error occurred when running ping: %s", err.Error()))
		return 2
	}
	return 0
}

func main() {
	os.Exit(run(os.Args[1:]))
}
